import 'dart:convert';\nimport 'dart:typed_data';\n\nimport 'package:dio/dio.dart';\nimport 'package:flutter_dotenv/flutter_dotenv.dart';\n\n/// Servicio de Transcripción de Audio usando Google Speech-to-Text\n///\n/// Google Speech-to-Text ofrece:\n/// - 60 minutos mensuales GRATIS\n/// - $300 crédito inicial en Google Cloud\n/// - Muy buena precisión para canciones\n///\n/// Alternativas:\n/// - OpenAI Whisper: $0.006/min (más barato)\n/// - Whisper.cpp: Gratis pero lento (local CPU)\nclass SpeechToTextService {\n  static const String _googleApiUrl = 'https://speech.googleapis.com/v1/speech:recognize';\n  \n  final Dio _dio;\n  final String _apiKey;\n  \n  SpeechToTextService({\n    Dio? dio,\n    String? apiKey,\n  }) : _dio = dio ?? Dio(),\n       _apiKey = apiKey ?? dotenv.env['GOOGLE_CLOUD_API_KEY'] ?? '';\n  \n  /// Transcribir audio a texto\n  /// \n  /// [audioBytes]: Audio en formato WAV/PCM\n  /// [languageCode]: Código de idioma (es-ES, en-US, etc.)\n  /// [sampleRate]: Tasa de muestreo (44100 para música)\n  Future<String> transcribeAudio({\n    required List<int> audioBytes,\n    String languageCode = 'es-ES',\n    int sampleRate = 44100,\n  }) async {\n    if (_apiKey.isEmpty) {\n      throw Exception('Google Cloud API Key no configurada. '\n          'Obtén una gratis en https://cloud.google.com');\n    }\n    \n    try {\n      // Convertir audio a base64 para Google API\n      final audioBase64 = base64Encode(audioBytes);\n      \n      final response = await _dio.post<Map<String, dynamic>>(\n        '$_googleApiUrl?key=$_apiKey',\n        data: {\n          'config': {\n            'encoding': 'LINEAR16',  // WAV 16-bit\n            'sampleRateHertz': sampleRate,\n            'languageCode': languageCode,\n            'enableAutomaticPunctuation': true,\n            'model': 'default',\n            // Para canciones, podemos usar 'video' model que es mejor para audio con música\n            'audioChannelCount': 1,  // Mono\n          },\n          'audio': {\n            'content': audioBase64,\n          },\n        },\n        options: Options(\n          headers: {\n            'Content-Type': 'application/json',\n          },\n        ),\n      );\n      \n      final data = response.data;\n      if (data == null || data['results'] == null) {\n        throw Exception('No se pudo transcribir el audio');\n      }\n      \n      final results = data['results'] as List<dynamic>;\n      if (results.isEmpty) {\n        return '';\n      }\n      \n      // Concatenar todas las alternativas\n      final transcripts = results.map((result) {\n        final alternatives = result['alternatives'] as List<dynamic>;\n        if (alternatives.isNotEmpty) {\n          return alternatives.first['transcript'] as String;\n        }\n        return '';\n      }).where((t) => t.isNotEmpty).join(' ');\n      \n      return transcripts;\n      \n    } on DioException catch (e) {\n      if (e.response?.statusCode == 403) {\n        throw Exception('API Key inválida o sin créditos. '\n            'Verifica en https://console.cloud.google.com');\n      }\n      throw Exception('Error de red: ${e.message}');\n    }\n  }\n  \n  /// Detectar idioma automáticamente\n  Future<String> detectLanguage(List<int> audioBytes) async {\n    if (_apiKey.isEmpty) {\n      return 'es-ES'; // Default\n    }\n    \n    try {\n      final audioBase64 = base64Encode(audioBytes);\n      \n      final response = await _dio.post<Map<String, dynamic>>(\n        '$_googleApiUrl?key=$_apiKey',\n        data: {\n          'config': {\n            'encoding': 'LINEAR16',\n            'sampleRateHertz': 44100,\n            'languageCode': 'es-ES',  // Base español\n            'alternativeLanguageCodes': ['en-US', 'pt-BR', 'fr-FR'],\n          },\n          'audio': {\n            'content': audioBase64,\n          },\n        },\n      );\n      \n      final data = response.data;\n      // Google no retorna el idioma detectado directamente en esta llamada\n      // Para simplificar, hacemos dos llamadas rápidas\n    } catch (_) {}\n    \n    // Fallback: detectar por análisis simple\n    return _detectLanguageSimple(audioBytes);\n  }\n  \n  /// Detección simple de idioma basado en características del audio\n  String _detectLanguageSimple(List<int> audioBytes) {\n    // Esta es una implementación muy básica\n    // En producción, usaríamos Google's language detection\n    return 'es-ES'; // Asumir español por ahora\n  }\n  \n  /// Transcribir y obtener timestamps (para letras sincronizadas)\n  Future<List<SpeechWord>> transcribeWithTimestamps({\n    required List<int> audioBytes,\n    String languageCode = 'es-ES',\n  }) async {\n    if (_apiKey.isEmpty) {\n      throw Exception('API Key no configurada');\n    }\n    \n    try {\n      final audioBase64 = base64Encode(audioBytes);\n      \n      final response = await _dio.post<Map<String, dynamic>>(\n        '$_googleApiUrl?key=$_apiKey',\n        data: {\n          'config': {\n            'encoding': 'LINEAR16',\n            'sampleRateHertz': 44100,\n            'languageCode': languageCode,\n            'enableWordTimeOffsets': true,  // Esto da timestamps por palabra\n            'enableAutomaticPunctuation': true,\n          },\n          'audio': {\n            'content': audioBase64,\n          },\n        },\n      );\n      \n      final data = response.data;\n      if (data == null || data['results'] == null) {\n        return [];\n      }\n      \n      final results = data['results'] as List<dynamic>;\n      final words = <SpeechWord>[];\n      \n      for (final result in results) {\n        final alternatives = result['alternatives'] as List<dynamic>;\n        if (alternatives.isNotEmpty) {\n          final alt = alternatives.first;\n          final wordsData = alt['words'] as List<dynamic>?;\n          \n          if (wordsData != null) {\n            for (final wordData in wordsData) {\n              final word = wordData['word'] as String;\n              final startTime = wordData['startTime'] as String?;\n              final endTime = wordData['endTime'] as String?;\n              \n              if (startTime != null && endTime != null) {\n                words.add(SpeechWord(\n                  text: word,\n                  startTimeMs: _parseGoogleTime(startTime),\n                  endTimeMs: _parseGoogleTime(endTime),\n                ));\n              }\n            }\n          }\n        }\n      }\n      \n      return words;\n      \n    } catch (e) {\n      // Fallback a transcripción sin timestamps\n      final transcript = await transcribeAudio(\n        audioBytes: audioBytes,\n        languageCode: languageCode,\n      );\n      \n      return [\n        SpeechWord(\n          text: transcript,\n          startTimeMs: 0,\n          endTimeMs: 10000, // Asumir 10 segundos\n        )\n      ];\n    }\n  }\n  \n  /// Parsear tiempo de Google (ej: "3.500s" a 3500ms)\n  int _parseGoogleTime(String timeStr) {\n    // Remover 's' del final\n    final seconds = double.tryParse(timeStr.replaceAll('s', '')) ?? 0.0;\n    return (seconds * 1000).round();\n  }\n}\n\n/// Palabra con timestamp para letras sincronizadas\nclass SpeechWord {\n  final String text;\n  final int startTimeMs;\n  final int endTimeMs;\n  \n  SpeechWord({\n    required this.text,\n    required this.startTimeMs,\n    required this.endTimeMs,\n  });\n}\n